package net.civeira.phylax.features.document.theme.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.tenant.domain.TenantReference;
import net.civeira.phylax.features.document.theme.application.visibility.ThemeEntityEnrichment;

public class InheritTenantExcludingRoot {

  /**
   * Constant for platformGlobalAccess scope
   *
   * @autogenerated FormulaPolicyGenerator
   */
  private static final String SCOPE_PLATFORM_GLOBAL_ACCESS = "platform:global_access";

  /**
   * @autogenerated FormulaPolicyGenerator
   * @param builder
   */
  public void calculate(@Observes ThemeEntityEnrichment builder) {
    Actor actor = builder.getActor();
    if (!actor.hasScope(SCOPE_PLATFORM_GLOBAL_ACCESS)) {
      builder.peek(dto -> dto.tenant(TenantReference.of(actor.getTenant().orElse(null))));
    }
  }
}
